using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.IO.Compression;using System.Threading.Tasks;using GlassBoard;
public static class UpdateTests {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,message);}
    static byte[] Archive(Dictionary<string,byte[]> data){using(var memory=new MemoryStream()){using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true))foreach(var item in data)using(var file=zip.CreateEntry(item.Key).Open())file.Write(item.Value,0,item.Value.Length);return memory.ToArray();}}
    static UpdateAsset Asset(string version){return new UpdateAsset{Name="GlassBoard_v"+version+"_User.zip",Size=1024,Type="file",FileUrl="https://raw.githubusercontent.com/SENLIN-SAMA/win-.-/main/GlassBoard_v"+version+"_User.zip",BlobSha=new string('a',40)};}
    public static int Main(string[] args){
        Check(UpdateRules.PackageVersion("GlassBoard_v0.9.6_User.zip")==new Version(0,9,6,0)&&UpdateRules.PackageVersion("GlassBoard_v0.9.6_Source.zip")==null,"user package naming");
        Check(!UpdateRules.Trusted("https://github.com.evil/SENLIN-SAMA/win-.-/releases/download/a/b")&&!UpdateRules.Trusted("http://github.com/SENLIN-SAMA/win-.-/releases/download/a/b")&&!UpdateRules.Trusted("https://raw.githubusercontent.com/other/repo/main/b.zip"),"update source confined to owner HTTPS repository");
        var draft=new UpdateRelease{Draft=true,Assets=new List<UpdateAsset>{Asset("99.0.0")}};var preview=new UpdateRelease{Prerelease=true,Assets=new List<UpdateAsset>{Asset("98.0.0")}};
        Check(UpdateRules.Choose(new[]{draft,preview},new[]{Asset("0.9.5"),Asset("0.9.6")}).Version==new Version(0,9,6,0),"root-file compatibility and draft/prerelease exclusion");
        var published=Asset("0.9.7");published.ReleaseUrl="https://github.com/SENLIN-SAMA/win-.-/releases/download/v0.9.7/"+published.Name;published.BlobSha=null;published.Digest="sha256:"+new string('b',64);Check(UpdateRules.Choose(new[]{new UpdateRelease{Assets=new List<UpdateAsset>{published}}},new[]{Asset("0.9.6")}).Version==new Version(0,9,7,0),"Releases and files choose newest");
        long now=DateTime.UtcNow.Ticks;Check(UpdateRules.Due(now,0)&&!UpdateRules.Due(now,now-TimeSpan.FromHours(2).Ticks)&&UpdateRules.Due(now,now-TimeSpan.FromDays(1).Ticks)&&UpdateRules.Due(now,now+1),"once-a-day startup checks");
        byte[] hello=Encoding.ASCII.GetBytes("hello");Check(UpdateRules.BlobHash(hello)=="b6fc4c620b67d95f953a5c1c1230aaab5db5a1b0","Git blob digest");var offer=new UpdateOffer{Size=5,BlobSha=UpdateRules.BlobHash(hello),Sha256=UpdateRules.Hash(hello)};UpdateRules.Verify(hello,offer);Reject(()=>UpdateRules.Verify(Encoding.ASCII.GetBytes("jello"),offer),"altered download rejected");
        string root=Path.Combine(Path.GetTempPath(),"GlassBoard-update-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        try{
            var data=new Dictionary<string,byte[]>{{"GlassBoard.exe",File.ReadAllBytes(args[0])},{"README.md",hello}};string sums=string.Join("\n",data.Select(p=>UpdateRules.Hash(p.Value)+"  "+p.Key))+"\n";data["SHA256SUMS.txt"]=Encoding.UTF8.GetBytes(sums);var archive=Archive(data.ToDictionary(p=>"GlassBoard/"+p.Key,p=>p.Value));
            var stage=Path.Combine(root,"stage");var hashes=UpdateApply.Extract(archive,stage,new Version(System.Diagnostics.FileVersionInfo.GetVersionInfo(args[0]).FileVersion));Check(hashes.Count==3,"verified user archive staged");
            var bad=new Dictionary<string,byte[]>(data);bad["../layout.json"]=hello;Reject(()=>UpdateApply.Extract(Archive(bad.ToDictionary(p=>"GlassBoard/"+p.Key,p=>p.Value)),Path.Combine(root,"bad1"),new Version(0,9,6,0)),"path traversal rejected");bad=new Dictionary<string,byte[]>(data);bad["layout.json"]=hello;Reject(()=>UpdateApply.Extract(Archive(bad.ToDictionary(p=>"GlassBoard/"+p.Key,p=>p.Value)),Path.Combine(root,"bad2"),new Version(0,9,6,0)),"configuration overwrite rejected");
            bad=new Dictionary<string,byte[]>(data);bad["README.md"]=Encoding.ASCII.GetBytes("tamper");Reject(()=>UpdateApply.Extract(Archive(bad.ToDictionary(p=>"GlassBoard/"+p.Key,p=>p.Value)),Path.Combine(root,"bad3"),new Version(0,9,6,0)),"internal file checksum required");Reject(()=>UpdateApply.Extract(archive,Path.Combine(root,"bad4"),new Version(999,0,0,0)),"wrong executable version rejected");
            string target=Path.Combine(root,"program");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"GlassBoard.exe"),"old binary");File.WriteAllText(Path.Combine(target,"README.md"),"old readme");File.WriteAllText(Path.Combine(target,"layout.json"),"user preferences");
            var plan=new UpdatePlan{Target=target,Stage=stage,Backup=Path.Combine(root,"backup-failed"),Files=hashes};Reject(()=>UpdateApply.Install(plan,path=>{if(path=="GlassBoard.exe")throw new IOException("injected write failure");}),"copy failure rolls back");Check(File.ReadAllText(Path.Combine(target,"GlassBoard.exe"))=="old binary"&&File.ReadAllText(Path.Combine(target,"README.md"))=="old readme"&&!File.Exists(Path.Combine(target,"SHA256SUMS.txt")),"all replaced and new files rolled back");
            plan.Backup=Path.Combine(root,"backup-success");UpdateApply.Install(plan);Check(File.ReadAllText(Path.Combine(target,"layout.json"))=="user preferences"&&UpdateRules.Hash(File.ReadAllBytes(Path.Combine(target,"GlassBoard.exe")))==hashes["GlassBoard.exe"],"successful install preserves configuration and installs expected binary");
            File.WriteAllText(Path.Combine(stage,"README.md"),"modified stage");plan.Backup=Path.Combine(root,"backup-tamper");Reject(()=>UpdateApply.Install(plan),"staged tamper rejected before modification");
        }finally{Directory.Delete(root,true);}
        Console.WriteLine("PASS: release/root selection, owner HTTPS, daily throttle, download/file checksums, archive/version/path protections, transactional install/rollback and configuration preservation.");
        if(args.Length>1&&args[1]=="--live"){var latest=UpdateService.Check().GetAwaiter().GetResult();Check(latest!=null,"live repository parsed");Console.WriteLine("LIVE: "+latest.Name+" "+latest.Size+" bytes");var bytes=UpdateService.Download(latest,System.Threading.CancellationToken.None,null).GetAwaiter().GetResult();Check(bytes.Length==latest.Size,"live Git blob download verified");Console.WriteLine("LIVE download checksum: PASS");}
        return 0;
    }
}
